package coverage

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Output is one generated file: path relative to the repository root.
type Output struct {
	Path string
	Data []byte
}

func esc(s string) string {
	s = strings.ReplaceAll(s, "\n", " ")
	return strings.ReplaceAll(s, "|", `\|`)
}

// Counts maps a status to a number.
type counts map[Status]int

func (c counts) Total() int {
	n := 0
	for _, v := range c {
		n += v
	}
	return n
}

// bar draws a 20 cell stacked bar using the status icons.
func bar(c counts) string {
	total := c.Total()
	if total == 0 {
		return strings.Repeat("▫️", 20)
	}
	const w = 20
	type rem struct {
		s Status
		r float64
	}
	cells := map[Status]int{}
	used := 0
	var rems []rem
	for _, s := range Statuses {
		exact := float64(c[s]) * w / float64(total)
		cells[s] = int(exact)
		used += int(exact)
		rems = append(rems, rem{s, exact - float64(int(exact))})
	}
	sort.SliceStable(rems, func(i, j int) bool { return rems[i].r > rems[j].r })
	for i := 0; used < w && i < len(rems); i++ {
		if c[rems[i].s] > 0 {
			cells[rems[i].s]++
			used++
		}
	}
	var b strings.Builder
	for _, s := range Statuses {
		b.WriteString(strings.Repeat(s.Icon(), cells[s]))
	}
	return b.String()
}

func pct(a, b int) string {
	if b == 0 {
		return "–"
	}
	return fmt.Sprintf("%.0f%%", float64(a)*100/float64(b))
}

func countCell(c counts) string {
	var p []string
	for _, s := range Statuses {
		if c[s] > 0 {
			p = append(p, fmt.Sprintf("%s %d", s.Icon(), c[s]))
		}
	}
	return strings.Join(p, " · ")
}

// Totals used by the overview and the badges.
type Totals struct {
	Routes, Registered, Verified, Web, WebRegistered int
	Features                                         counts
	RouteStatus                                      counts
}

func (m *Model) Totals() Totals {
	t := Totals{Features: counts{}, RouteStatus: counts{}}
	for _, r := range m.Routes {
		t.Routes++
		t.RouteStatus[r.Status]++
		if r.Registered {
			t.Registered++
		}
		if r.Registered && len(r.Passing) > 0 {
			t.Verified++
		}
		if r.Web {
			t.Web++
			if r.Registered {
				t.WebRegistered++
			}
		}
	}
	for _, f := range m.Files {
		for _, x := range f.Features {
			t.Features[x.Status]++
		}
	}
	return t
}

func routeCounts(rs []Route) (c counts, reg, ver int) {
	c = counts{}
	for _, r := range rs {
		c[r.Status]++
		if r.Registered {
			reg++
		}
		if r.Registered && len(r.Passing) > 0 {
			ver++
		}
	}
	return
}

func (m *Model) routesOf(group string) []Route {
	var out []Route
	for _, r := range m.Routes {
		if r.Group == group {
			out = append(out, r)
		}
	}
	return out
}

func (m *Model) groupSlugs() []string {
	var s []string
	for k := range m.Overlay.Groups {
		s = append(s, k)
	}
	sort.Strings(s)
	return s
}

// scenarioLinks renders up to a few scenario ids as links.
func (m *Model) scenarioLinks(ids []string, up string, max int) string {
	var p []string
	for i, id := range ids {
		if i == max {
			p = append(p, fmt.Sprintf("+%d", len(ids)-max))
			break
		}
		p = append(p, fmt.Sprintf("[`%s`](%scontract/scenarios/%s.json)", id, up, m.ScenarioFile[id]))
	}
	return strings.Join(p, "<br>")
}

func (m *Model) ruleLinks(ids []string, up string) string {
	var p []string
	for _, id := range ids {
		p = append(p, fmt.Sprintf("[`%s`](%scontract/specs/%s.md)", id, up, m.RuleFile[id]))
	}
	return strings.Join(p, "<br>")
}

// Render produces every generated file.
func (m *Model) Render() []Output {
	var out []Output
	add := func(p string, s string) { out = append(out, Output{p, []byte(s)}) }
	add("docs/COVERAGE.md", m.renderOverview())
	for _, slug := range m.groupSlugs() {
		add("docs/coverage/api-"+slug+".md", m.renderGroup(slug))
	}
	for _, ff := range m.Files {
		add("docs/coverage/"+ff.Area+".md", m.renderArea(ff))
	}
	add("docs/coverage/status.json", m.renderJSON())
	if rd, ok := m.renderReadme(); ok {
		add("README.md", rd)
	}
	t := m.Totals()
	add("docs/coverage/badge-routes.svg", badge("API routes", fmt.Sprintf("%d/%d registered", t.Registered, t.Routes), "#2ea44f"))
	add("docs/coverage/badge-verified.svg", badge("contract-verified", fmt.Sprintf("%d/%d routes", t.Verified, t.Routes), "#0969da"))
	return out
}

func (m *Model) renderOverview() string {
	t := m.Totals()
	var b strings.Builder
	w := func(f string, a ...any) { fmt.Fprintf(&b, f, a...) }
	w("<!-- Generated by `go run ./cmd/conformance coverage`. Do not edit; edit docs/coverage/overlay.json or docs/coverage/features/*.json. -->\n\n")
	w("# What Tinyfin does and does not do\n\n")
	w("Whole-backend coverage of Jellyfin %s (%s), computed from the reference's OpenAPI document,\nthe routes Tinyfin registers and the contract scenarios that pass in `docs/contract/baseline.json`.\n", m.OpenAPI.Version, m.OpenAPI.Source)
	w("How to read and edit this: [`docs/coverage/README.md`](coverage/README.md). Machine-readable copy: [`docs/coverage/status.json`](coverage/status.json).\n\n")
	w("| Legend | |\n|---|---|\n")
	w("| ✅ supported | works; for routes: registered, and the contract has a passing scenario unless marked *no scenario* |\n")
	w("| 🟡 partial | exists with known limits (see notes) |\n")
	w("| 🗓️ planned | intended, not built |\n")
	w("| ⛔ not-planned | deliberately out of scope or not on any roadmap |\n")
	w("| ↔️ divergent-by-design | behaves differently from the reference on purpose |\n\n")
	w("## Totals\n\n")
	w("| Measure | Value |\n|---|---|\n")
	w("| Reference operations (OpenAPI %s) | %d |\n", m.OpenAPI.Version, t.Routes)
	w("| Registered by Tinyfin | **%d** (%s) |\n", t.Registered, pct(t.Registered, t.Routes))
	w("| Registered **and** a passing contract scenario | **%d** (%s) |\n", t.Verified, pct(t.Verified, t.Routes))
	w("| Called by the official web client (docs/11) and registered | %d of %d (%s) |\n", t.WebRegistered, t.Web, pct(t.WebRegistered, t.Web))
	w("| Routes Tinyfin serves that the OpenAPI document lacks | %d (legacy aliases the web client needs, `/socket`, HLS) |\n", len(m.Extras))
	w("| Non-route features tracked | %d (%s) |\n\n", t.Features.Total(), countCell(t.Features))
	w("### Routes by status\n\n%s %s\n\n", bar(t.RouteStatus), countCell(t.RouteStatus))
	w("```mermaid\npie showData title Reference operations by status\n")
	for _, s := range Statuses {
		if t.RouteStatus[s] > 0 {
			w("    %q : %d\n", string(s), t.RouteStatus[s])
		}
	}
	w("```\n\n### Non-route features by status\n\n%s %s\n\n", bar(t.Features), countCell(t.Features))
	w("```mermaid\npie showData title Features by status\n")
	for _, s := range Statuses {
		if t.Features[s] > 0 {
			w("    %q : %d\n", string(s), t.Features[s])
		}
	}
	w("```\n\n## HTTP API by controller group\n\n")
	w("Registered = Tinyfin serves the route. Verified = registered with a passing contract scenario.\n\n")
	w("| Group | Ops | Registered | Verified | Progress | Status |\n|---|---|---|---|---|---|\n")
	for _, slug := range m.groupSlugs() {
		rs := m.routesOf(slug)
		c, reg, ver := routeCounts(rs)
		w("| [%s](coverage/api-%s.md) | %d | %d (%s) | %d (%s) | %s | %s |\n", m.Overlay.Groups[slug].Title, slug, len(rs), reg, pct(reg, len(rs)), ver, pct(ver, len(rs)), bar(c), countCell(c))
	}
	w("\n### By OpenAPI tag (controller)\n\n| Tag | Ops | Registered | Verified | Status |\n|---|---|---|---|---|\n")
	tags := map[string][]Route{}
	var tl []string
	for _, r := range m.Routes {
		if _, ok := tags[r.Tag]; !ok {
			tl = append(tl, r.Tag)
		}
		tags[r.Tag] = append(tags[r.Tag], r)
	}
	sort.Strings(tl)
	for _, tg := range tl {
		c, reg, ver := routeCounts(tags[tg])
		w("| %s | %d | %d | %d | %s |\n", tg, len(tags[tg]), reg, ver, countCell(c))
	}
	w("\n## Subsystems and features\n\n| Area | Features | Progress | Status |\n|---|---|---|---|\n")
	for _, ff := range m.Files {
		c := counts{}
		for _, f := range ff.Features {
			c[f.Status]++
		}
		w("| [%s](coverage/%s.md) | %d | %s | %s |\n", ff.Title, ff.Area, len(ff.Features), bar(c), countCell(c))
	}
	w("\n## Behavior contract (derived)\n\nThe contract is what makes \"supported\" checkable: `go run ./cmd/conformance run` against a throwaway Tinyfin, compared with the committed baseline.\n\n")
	w("| Spec | Rules | Rules with a scenario | Scenarios | Passing |\n|---|---|---|---|---|\n")
	var sr, sc, ss, sp int
	for _, s := range m.Specs {
		w("| [%s](contract/specs/%s.md) | %d | %d | %d | %d |\n", s.Area, s.Area, s.Rules, s.Covered, s.Scenarios, s.Passing)
		sr, sc, ss, sp = sr+s.Rules, sc+s.Covered, ss+s.Scenarios, sp+s.Passing
	}
	w("| **total** | %d | %d | %d | %d |\n\n", sr, sc, ss, sp)
	w("## Biggest gaps (planned or not planned, web-client facing)\n\n")
	w("Operations the official web client mentions (docs/11) that Tinyfin does not register:\n\n| Route | Status | Group | Notes |\n|---|---|---|---|\n")
	n := 0
	for _, r := range m.Routes {
		if r.Web && !r.Registered && r.Method != "HEAD" {
			w("| `%s` | %s %s | %s | %s |\n", r.ID(), r.Status.Icon(), r.Status, m.Overlay.Groups[r.Group].Title, esc(r.Notes))
			n++
		}
	}
	if n == 0 {
		w("| – | | | |\n")
	}
	w("\n")
	return b.String()
}

func (m *Model) renderGroup(slug string) string {
	g := m.Overlay.Groups[slug]
	rs := m.routesOf(slug)
	c, reg, ver := routeCounts(rs)
	var b strings.Builder
	w := func(f string, a ...any) { fmt.Fprintf(&b, f, a...) }
	w("<!-- Generated by `go run ./cmd/conformance coverage`. Do not edit. -->\n\n# API: %s\n\n%s\n\n", g.Title, g.Summary)
	w("[Overview](../COVERAGE.md) · %d operations · %d registered (%s) · %d verified · %s\n\n%s\n\n", len(rs), reg, pct(reg, len(rs)), ver, countCell(c), bar(c))
	w("Columns: **Auth** is the reference's authorization policy; **Web** = mentioned in docs/11 (called by the official web client); **Tests** = scenarios that exercise the route (passing / total).\n\n")
	tagSeen := map[string]bool{}
	for _, r := range rs {
		if tagSeen[r.Tag] {
			continue
		}
		tagSeen[r.Tag] = true
		w("## %s\n\n| Status | Route | Auth | Web | Tests | What Tinyfin does / notes |\n|---|---|---|---|---|---|\n", r.Tag)
		for _, x := range rs {
			if x.Tag != r.Tag {
				continue
			}
			st := x.Status.Icon() + " " + string(x.Status)
			if x.Unverified {
				st += " *(no scenario)*"
			}
			web := ""
			if x.Web {
				web = "yes"
			}
			dep := ""
			if x.Deprecated {
				dep = " *(deprecated)*"
			}
			note := x.Notes
			if x.Via != "" {
				note = strings.TrimSpace("Served by `" + x.Via + "`. " + note)
			}
			if x.Reference != "" {
				note = strings.TrimSpace(note + " Reference: " + x.Reference)
			}
			if x.Priority != "" {
				note += " (priority: " + x.Priority + ")"
			}
			tests := ""
			if len(x.Scenarios) > 0 {
				tests = fmt.Sprintf("%d/%d", len(x.Passing), len(x.Scenarios))
			}
			w("| %s | `%s`%s | %s | %s | %s | %s |\n", st, x.ID(), dep, esc(x.Policy), web, tests, esc(note))
		}
		w("\n")
	}
	var fs []string
	for _, ff := range m.Files {
		for _, f := range ff.Features {
			for _, rt := range f.Routes {
				for _, r := range rs {
					if r.ID() == rt {
						fs = append(fs, fmt.Sprintf("- [`%s`](%s.md) %s", f.ID, ff.Area, f.Title))
						goto next
					}
				}
			}
		next:
		}
	}
	if len(fs) > 0 {
		w("## Related features\n\n%s\n", strings.Join(fs, "\n"))
	}
	return b.String()
}

func (m *Model) renderArea(ff FeatureFile) string {
	c := counts{}
	for _, f := range ff.Features {
		c[f.Status]++
	}
	var b strings.Builder
	w := func(f string, a ...any) { fmt.Fprintf(&b, f, a...) }
	w("<!-- Generated by `go run ./cmd/conformance coverage`. Do not edit; edit docs/coverage/features/%s.json. -->\n\n# %s\n\n%s\n\n", ff.Area, ff.Title, ff.Summary)
	w("[Overview](../COVERAGE.md) · %d features · %s\n\n%s\n\n", len(ff.Features), countCell(c), bar(c))
	w("| Status | Feature | Jellyfin 12.2 | Tinyfin | Evidence | Notes |\n|---|---|---|---|---|---|\n")
	for _, f := range ff.Features {
		st := f.Status.Icon() + " " + string(f.Status)
		if f.Unverified {
			st += " *(unverified)*"
		}
		var ev []string
		if len(f.SpecRules) > 0 {
			ev = append(ev, "spec: "+m.ruleLinks(f.SpecRules, "../"))
		}
		if len(f.Scenarios) > 0 {
			pass := 0
			for _, s := range f.Scenarios {
				if m.Baseline[s] == "pass" {
					pass++
				}
			}
			ev = append(ev, fmt.Sprintf("scenarios %d/%d pass: %s", pass, len(f.Scenarios), m.scenarioLinks(f.Scenarios, "../", 3)))
		}
		if len(f.Code) > 0 {
			var cs []string
			for _, p := range f.Code {
				cs = append(cs, fmt.Sprintf("[`%s`](../../%s)", p, p))
			}
			ev = append(ev, "code: "+strings.Join(cs, "<br>"))
		}
		if len(f.Routes) > 0 {
			ev = append(ev, "routes: `"+strings.Join(f.Routes, "`<br>`")+"`")
		}
		note := f.Notes
		if f.Unverified {
			note = strings.TrimSpace(note + " Unverified: " + f.UnverifiedR)
		}
		if f.Priority != "" {
			note += " (priority: " + f.Priority + ")"
		}
		w("| %s | **%s**<br>`%s` | %s | %s | %s | %s |\n", st, esc(f.Title), f.ID, esc(f.Reference), esc(f.Description), strings.Join(ev, "<br>"), esc(note))
	}
	w("\n")
	return b.String()
}

func (m *Model) renderJSON() string {
	type jr struct {
		ID         string   `json:"id"`
		Tag        string   `json:"tag"`
		Group      string   `json:"group"`
		Policy     string   `json:"policy"`
		Status     Status   `json:"status"`
		Registered bool     `json:"registered"`
		Verified   bool     `json:"verified"`
		Web        bool     `json:"web"`
		Scenarios  []string `json:"scenarios,omitempty"`
		Notes      string   `json:"notes,omitempty"`
		Priority   string   `json:"priority,omitempty"`
	}
	t := m.Totals()
	doc := struct {
		Reference string         `json:"reference"`
		Totals    map[string]any `json:"totals"`
		Routes    []jr           `json:"routes"`
		Features  []Feature      `json:"features"`
		Extras    []string       `json:"registered_not_in_openapi"`
	}{Reference: m.OpenAPI.Source + " " + m.OpenAPI.Version}
	doc.Totals = map[string]any{
		"operations": t.Routes, "registered": t.Registered, "verified": t.Verified,
		"routes_by_status": t.RouteStatus, "features_by_status": t.Features,
	}
	for _, r := range m.Routes {
		doc.Routes = append(doc.Routes, jr{r.ID(), r.Tag, r.Group, r.Policy, r.Status, r.Registered,
			r.Registered && len(r.Passing) > 0, r.Web, r.Scenarios, r.Notes, r.Priority})
	}
	for _, ff := range m.Files {
		doc.Features = append(doc.Features, ff.Features...)
	}
	doc.Extras = m.Extras
	raw, _ := json.MarshalIndent(doc, "", " ")
	return string(raw) + "\n"
}

func badge(label, value, color string) string {
	lw := 7*len(label) + 12
	vw := 7*len(value) + 12
	var b bytes.Buffer
	fmt.Fprintf(&b, `<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="20" role="img" aria-label="%s: %s">`+
		`<rect width="%d" height="20" fill="#555"/><rect x="%d" width="%d" height="20" fill="%s"/>`+
		`<g fill="#fff" font-family="Verdana,DejaVu Sans,sans-serif" font-size="11" text-anchor="middle">`+
		`<text x="%d" y="14">%s</text><text x="%d" y="14">%s</text></g></svg>`+"\n",
		lw+vw, label, value, lw, lw, vw, color, lw/2, label, lw+vw/2, value)
	return b.String()
}

// Write stores outputs under root.
func Write(root string, outs []Output) error {
	for _, o := range outs {
		p := filepath.Join(root, o.Path)
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(p, o.Data, 0o644); err != nil {
			return err
		}
	}
	return nil
}

// Check returns the validation errors plus every generated file that is
// missing or out of date.
func Check(root string, m *Model) []string {
	errs := append([]string(nil), m.Errors...)
	for _, o := range m.Render() {
		got, err := os.ReadFile(filepath.Join(root, o.Path))
		if err != nil {
			errs = append(errs, o.Path+": missing (run `go run ./cmd/conformance coverage`)")
		} else if !bytes.Equal(got, o.Data) {
			errs = append(errs, o.Path+": out of date (run `go run ./cmd/conformance coverage`)")
		}
	}
	return errs
}

// ImportOpenAPI converts an OpenAPI document into docs/coverage/openapi-ops.json.
func ImportOpenAPI(doc []byte, source string) ([]byte, error) {
	type opDoc struct {
		Tags        []string              `json:"tags"`
		OperationID string                `json:"operationId"`
		Deprecated  bool                  `json:"deprecated"`
		Security    []map[string][]string `json:"security"`
	}
	var d struct {
		Info struct {
			Version string `json:"version"`
		} `json:"info"`
		Paths map[string]map[string]json.RawMessage `json:"paths"`
	}
	if err := json.Unmarshal(doc, &d); err != nil {
		return nil, err
	}
	f := OpsFile{Source: source, Version: d.Info.Version}
	for p, ms := range d.Paths {
		for method, rawOp := range ms {
			switch method {
			case "get", "post", "put", "delete", "head", "patch":
			default:
				continue
			}
			var o opDoc
			if err := json.Unmarshal(rawOp, &o); err != nil {
				return nil, fmt.Errorf("%s %s: %w", method, p, err)
			}
			pol := "Anonymous"
			if len(o.Security) > 0 {
				pol = "Authenticated"
				for _, v := range o.Security[0] {
					if len(v) > 0 {
						pol = v[0]
					}
				}
			}
			tag := ""
			if len(o.Tags) > 0 {
				tag = o.Tags[0]
			}
			f.Operations = append(f.Operations, Op{strings.ToUpper(method), p, tag, o.OperationID, pol, o.Deprecated})
		}
	}
	sort.Slice(f.Operations, func(i, j int) bool { return f.Operations[i].ID() < f.Operations[j].ID() })
	raw, err := json.MarshalIndent(f, "", " ")
	return append(raw, '\n'), err
}

const (
	readmeStart = "<!-- coverage:start -->"
	readmeEnd   = "<!-- coverage:end -->"
)

// renderReadme replaces the block between the coverage markers of README.md
// with the generated summary; ok is false when README.md has no markers.
func (m *Model) renderReadme() (string, bool) {
	raw, err := os.ReadFile(filepath.Join(m.Root, "README.md"))
	if err != nil {
		return "", false
	}
	src := string(raw)
	i, j := strings.Index(src, readmeStart), strings.Index(src, readmeEnd)
	if i < 0 || j < i {
		return "", false
	}
	t := m.Totals()
	var b strings.Builder
	w := func(f string, a ...any) { fmt.Fprintf(&b, f, a...) }
	w("%s\n", readmeStart)
	w("![API routes](docs/coverage/badge-routes.svg) ![contract-verified](docs/coverage/badge-verified.svg)\n\n")
	w("Measured against the Jellyfin %s OpenAPI document (%d operations): **%d registered (%s)**, **%d with a passing contract scenario (%s)**.\n\n",
		m.OpenAPI.Version, t.Routes, t.Registered, pct(t.Registered, t.Routes), t.Verified, pct(t.Verified, t.Routes))
	w("| Route status | Count | Non-route features | Count |\n|---|---|---|---|\n")
	for _, s := range Statuses {
		w("| %s %s | %d | %s %s | %d |\n", s.Icon(), s, t.RouteStatus[s], s.Icon(), s, t.Features[s])
	}
	w("\nPer controller and per subsystem, with what the reference does and what Tinyfin does: **[docs/COVERAGE.md](docs/COVERAGE.md)**.\n")
	w("%s", readmeEnd)
	return src[:i] + b.String() + src[j+len(readmeEnd):], true
}
